SELECT p.subject_id, s.stay_id, m.map_max, percentile_cont(0.75) within GROUP (ORDER BY m.map_max) AS median_map FROM patients p JOIN admissions s ON p.subject_id = s.subject_id JOIN labevents m ON s.stay_id = m.subject_id AND p.subject_id = m.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 87 AND EXTRACT(YEAR FROM p.anchor_year) BETWEEN 82 AND 92 GROUP BY p.subject_id, s.stay_id, m.map_max ORDER BY p.subject_id, s.stay_id NULLS LAST;